weak_algorithms := {"DES", "RC4", "3DES", "MD2", "MD4", "MD5", "SHA1", "ECB", "Blowfish", "XOR", "ROT-25", "TEA", "AES-128"}
weak_protocols := {"ssl-v2", "ssl-v3", "tls-1.0", "tls-1.1", "legacy", "insecure"}
weak_hashing := {"sha1", "md5"}
weak_signatures := {"rsa-sha1", "dsa-sha1"}
weak_curves := {"secp112r1"}
weak_cipher_suites := {"RC4", "DES-CBC3-SHA", "NULL", "EXPORT"}

# Check if a string value matches weak patterns
is_weak_string(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    weak_algorithms[_] == lower_value
} else {
    value.ir_type == "String"
    lower_value := lower(value.value)
    weak_protocols[_] == lower_value
} else {
