    lower_value := lower(value.value)
    weak_hashing[_] == lower_value
} else {
    value.ir_type == "String"
    lower_value := lower(value.value)
    weak_signatures[_] == lower_value
} else {
    value.ir_type == "String"
    lower_value := lower(value.value)
    weak_curves[_] == lower_value
}

# Check for insufficient key sizes
is_insufficient_key_size(value) {
    value.ir_type == "Integer"
    value.value < 2048  # RSA minimum
