    value.ir_type == "Integer"
    value.value < 256   # Symmetric minimum
} else {
    value.ir_type == "Integer"
    value.value == 56   # DES key length
} else {
    value.ir_type == "Integer"
    value.value == 1024  # RSA weak key size
}

# Check for weak block modes
is_weak_mode(value) {
    value.ir_type == "String"
    lower(value.value) == "ecb"
}

# Main detection rule for weak cryptographic algorithms
